            {"name": "goal.create", "usage": "goal create --title TEXT --request-id ID --recovery-generation GENERATION [--notes TEXT] [--horizon-text TEXT]", "description": "创建目标；GENERATION 取 context.recoveryGeneration，空值传 none"},
