            {"name": "goal.action.edit", "usage": "goal action edit GOAL_ID ACTION_ID --title TEXT --notes TEXT --phase-id ID|none --expected-revision N --recovery-generation GENERATION", "description": "编辑尚未转为任务的候选行动"},
